export const now=()=>new Date().toISOString(); export const id=(kind:string)=>`${kind}_${randomBytes(10).toString('hex')}`;
export type RunStatus='running'|'completed'|'failed'|'cancelled'; export type StoredRun={id:string;accountId:string;model:string;threadId?:string;providerTurnId?:string;fingerprint:string;status:RunStatus;outputStarted:boolean;cancelRequested:boolean;apiKeyId?:string;responseFormatOriginal?:unknown};
type DbRun={id:string;account_id:string;thread_id:string|null;provider_turn_id:string|null;fingerprint:string;status:RunStatus;output_started:number;cancel_requested:number}; type DbThread={account_id:string;provider_thread_id:string}; type DbAccount={id:string;alias:string;state:Account['state'];models:string;quota:string;health:number;active_runs:number;cooldown_until:string|null;tier:string|null;home_ref:string|null};
const terminal=new Set<RunStatus>(['completed','failed','cancelled']);
