 credentialLease(leaseId:string){this.expireCredentialLeases();const row=this.db.prepare('SELECT l.id,l.account_id AS accountId,a.alias,a.models,l.holder,l.issued_at AS issuedAt,l.expires_at AS expiresAt FROM credential_leases l JOIN accounts a ON a.id=l.account_id WHERE l.id=?').get(leaseId) as {id:string;accountId:string;alias:string;models:string;holder:string|null;issuedAt:string;expiresAt:string}|undefined;return row&&{id:row.id,accountId:row.accountId,alias:row.alias,holder:row.holder,issuedAt:row.issuedAt,expiresAt:row.expiresAt,models:JSON.parse(row.models) as string[]} satisfies CredentialLease;}
 credentialLeases(){this.expireCredentialLeases();return (this.db.prepare('SELECT id FROM credential_leases ORDER BY issued_at').all() as {id:string}[]).map(row=>this.credentialLease(row.id)!).filter(Boolean);}
